head.script:
scwin.screenId = "jldfil01050";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_fssUnqNo", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["fssUnqNo"] ?? ""); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.fnSetStopTradding = fnSetStopTradding;

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.moveStep = undefined; scwin.result = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil01050.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.tableId_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.tableId_oncellclick = function (rowIndex, columnIndex, columnId) {
    try { { const d = $c.util.getComponent('dlt_stopList'); if (d && typeof scwin.fnSetStopTradding === 'function') { scwin.fnSetStopTradding(String(d.getCellData(rowIndex, "isuSrtCd")), String(d.getCellData(rowIndex, "isuKorNm")), String(d.getCellData(rowIndex, "isuEngAbbrv")), String(d.getCellData(rowIndex, "isuCd")), String(d.getCellData(rowIndex, "eqtyoptIsuObjYn"))); } } 
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil01050.tableId_oncellclick' }); }
};

/**
 * @event
 * @name scwin.img_85_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_85_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_85_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.findCompany()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil01050.img_85_onclick' }); }
};

/**
 * @event
 * @name scwin.img_110_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_110_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_110_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnStopTradding()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil01050.img_110_onclick' }); }
};

/**
 * @event
 * @name scwin.img_130_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_130_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_130_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goWrite()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil01050.img_130_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_documentWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_documentWriteReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil01050.tx_fn_documentWrite" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_goWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/submission/disclosurereg.do?method=registerDisclosure",
        ref: "dma_goWriteReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil01050.tx_fn_goWrite" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fnStopTradding
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnStopTradding = async function () {
    const sbmOptions = {
        id: "tx_fnStopTradding", target: "dlt_stopList=list",
        method: "post",
        action: "/submission/disclosure.do",
        ref: "dma_fnStopTraddingReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil01050.tx_fnStopTradding" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.findCompany
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.findCompany = function () {
    /* sdd-asis-lifecycle:begin fn_findCompany — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let corpSearchURL = '/jldfil00033/jldfil00033.xml?method=loadInitPage&ldMktTpCd=' + dma_disclosureVo.get("ldMktTpCd") + '';
    if ('34001' === $c.util.getComponent('ipt_disclsMaindocFormCd').getValue() || '34004' === $c.util.getComponent('ipt_disclsMaindocFormCd').getValue()) {
        corpSearchURL += "&preKonex=Y";
    }
    (Promise.resolve($c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(corpSearchURL), { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "570", type: "pageFramePopup" }, {})).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("corpWin"); this.closed = true; } });
/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd kisComCd repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo comEngAbbrv eqtyoptIsuObjYn
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, comEngAbbrv, eqtyoptIsuObjYn) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_txtisurCd").setValue(isurCd);
    $c.util.getComponent("ipt_txtfssUnqNo").setValue(fssUnqNo);
    $c.util.getComponent("ipt_txtcomNm").setValue(comNm + " " + "주권");
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent("dma_documentWriteReq").set("tgtComEngNm", comEngAbbrv);
    $c.util.getComponent("dma_documentWriteReq").set("eqtyoptIsuObjYn", eqtyoptIsuObjYn);
    $c.util.getComponent('dma_documentWriteReq').set('chkPop', 'Y');
    $c.util.getComponent('dma_documentWriteReq').set('corpisuBasTpCd', "1");
    $('#targetNm').text('대상회사명');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.documentWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.documentWrite = async function () {
    /* sdd-asis-lifecycle:begin fn_documentWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.corpForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument';
    await scwin.tx_fn_documentWrite();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.registerProcess
 * @author Inswave
 * @date 2026. 09. 29
 * @param applNo docNo formCd formVer wrtrptMaindocTpCd method
 * @returns
 * @hidden N
*/
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method) {
    /* sdd-asis-lifecycle:begin fn_registerProcess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_documentWriteReq').set('applNo', applNo);
    if (applNo.length == 14) {
        await scwin.documentWrite();
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.registerMessage
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg
 * @returns
 * @hidden N
*/
scwin.registerMessage = async function (msg) {
    /* sdd-asis-lifecycle:begin registerMessage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert(msg);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goWrite = async function () {
    /* sdd-asis-lifecycle:begin fn_goWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('ipt_txtisurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisurCd').getValue())) === '' || ($c.util.getComponent('ipt_txtfssUnqNo').getValue() == null ? '' : String($c.util.getComponent('ipt_txtfssUnqNo').getValue())) === '' || ($c.util.getComponent('ipt_txtcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtcomNm').getValue())) === '' || $c.util.getComponent('dma_documentWriteReq').get('chkPop') === '') {
        await $c.win.alert('대상회사를 선택하십시요');
        return;
    }
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent("dma_documentWriteReq").set("tgtComEngNm", $c.util.getComponent("dma_documentWriteReq").get("tgtComEngNm"));
    scwin.moveStep = true;
    $c.util.getComponent("dma_documentWriteReq").set("eqtyoptIsuObjYn", $c.util.getComponent("dma_documentWriteReq").get("eqtyoptIsuObjYn"));
    (document.disclosureFrm || { elements: [] }).action = '/submission/disclosurereg.do?method=registerDisclosure';
    (document.disclosureFrm || { elements: [] }).target = 'tempSaveFrame';
    await scwin.tx_fn_goWrite();
    /* sdd-asis-lifecycle:end */
};


function fnSetStopTradding(isuSrtCd, isuKorNm, isuEngNm, isuCd, eqtyoptIsuObjYn) {
    /* sdd-asis-lifecycle:begin fnSetStopTradding — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_txtcomNm").setValue(isuKorNm);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', isuSrtCd);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', isuSrtCd);
    $c.util.getComponent("dma_documentWriteReq").set("tgtComEngNm", isuEngNm);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuCd', isuCd);
    $c.util.getComponent("dma_documentWriteReq").set("eqtyoptIsuObjYn", eqtyoptIsuObjYn);
    $c.util.getComponent('dma_documentWriteReq').set('corpisuBasTpCd', "2");
    $('#targetNm').text('대상종목명');
    /* sdd-asis-lifecycle:end */
}

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.fnStopTradding_done
 * @author Inswave
 * @date 2026. 09. 29
 * @param dataList
 * @returns
 * @hidden N
*/
scwin.fnStopTradding_done = async function (dataList) {
    /* sdd-asis-lifecycle:begin fnStopTradding_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof dataList === "string" ? JSON.parse(dataList) : dataList);
    if (scwin.result.resultAuth === 'Y') {
        $c.util.getComponent('tableId').setStyle("display", "");
        let html = "";
        $(scwin.result.list).each(function(i, item) {
                html += "<tr style=\"cursor: pointer;\" onclick=\"fnSetStopTradding('" + item.isuSrtCd + "', '" + item.isuKorNm + "', '" + item.isuEngAbbrv + "', '" + item.isuCd + "', '" + item.eqtyoptIsuObjYn + "')\">";
                html += "  <td class='td_board'>" + item.isuCd + "</td>";
                html += "  <td class='td_board'>" + item.isuKorNm + "</td>";
                html += "  <td class='td_board'>" + item.isuEngAbbrv + "</td>";
                html += "</tr>";
        });
        (console.error('[sdd] 이 화면 문서에 #txt_bodyList 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#txt_bodyList")).html(html);
    } else {
        $c.util.getComponent('tableId').setStyle("display", "none");
        await $c.win.alert('대상회사는 팀에 배정된 법인이 아닙니다.');
        return;
    }
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.fnStopTradding
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnStopTradding = async function () {
    const r = await scwin.tx_fnStopTradding();
    try {
        scwin.fnStopTradding_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil01050.fnStopTradding' });
    }
    return r;
};
